class PriceEngine:
    def __init__(self):
        self.discount_rates = {
            'basic': 0.0,
            'pro': 0.1
        }

    def price(self, plan, amount):
        if plan not in self.discount_rates:
            raise KeyError(f"Unknown plan: {plan}")

        discount_rate = self.discount_rates[plan]
        discounted_price = amount * (1 - discount_rate)
        return round(discounted_price, 2)

    def discounts(self):
        return dict(self.discount_rates)
